package com.bank.spark.model;

// Describes a skew situation to classify.
public class SkewSituation {
    public enum Operation { JOIN, GROUP_BY }

    private final String name;
    private final Operation operation;
    private final boolean bothSidesSkewed;
    private final int hotKeyCount;

    public SkewSituation(String name, Operation operation, boolean bothSidesSkewed, int hotKeyCount) {
        this.name = name;
        this.operation = operation;
        this.bothSidesSkewed = bothSidesSkewed;
        this.hotKeyCount = hotKeyCount;
    }

    public String getName() { return name; }
    public Operation getOperation() { return operation; }
    public boolean isBothSidesSkewed() { return bothSidesSkewed; }
    public int getHotKeyCount() { return hotKeyCount; }
}
