package com.bank.spark.service;

import com.bank.spark.model.SkewSituation;

// Recommends the skew-handling strategy in the correct priority order.
public class SkewStrategyAdvisor {

    private static final int FEW_HOT_KEYS = 10;

    public String recommend(SkewSituation s) {
        // 1) groupBy skew: AQE skew-JOIN does not cover it → salting with two-stage agg.
        if (s.getOperation() == SkewSituation.Operation.GROUP_BY) {
            return "SALTING (two-stage aggregation) — AQE skew-join does not cover groupBy skew";
        }
        // 2) both sides skewed on same key: AQE often insufficient → salting.
        if (s.isBothSidesSkewed()) {
            return "SALTING — both sides skewed on the same key; AQE split+replicate can blow up";
        }
        // 3) few known hot keys: isolate-and-broadcast is clean.
        if (s.getHotKeyCount() > 0 && s.getHotKeyCount() <= FEW_HOT_KEYS) {
            return "ISOLATE-AND-BROADCAST the " + s.getHotKeyCount()
                    + " hot keys (broadcast their small-side rows) + normal join for cold keys";
        }
        // 4) default: single-side join skew → let AQE handle it, no code change.
        return "AQE SKEW JOIN (automatic, no code change) — try this first";
    }
}
