package com.bank.spark;

import com.bank.spark.model.SkewSituation;
import com.bank.spark.service.SkewStrategyAdvisor;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SkewStrategyDemo {

    private static final Logger log = Logger.getLogger(SkewStrategyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SkewStrategyAdvisor advisor = new SkewStrategyAdvisor();

        List<SkewSituation> situations = List.of(
                new SkewSituation("txns ⋈ accounts (one hot account)", SkewSituation.Operation.JOIN, false, 1),
                new SkewSituation("groupBy accountId totals (hot account)", SkewSituation.Operation.GROUP_BY, false, 1),
                new SkewSituation("txns ⋈ counterparties (both skewed)", SkewSituation.Operation.JOIN, true, 1),
                new SkewSituation("txns ⋈ accounts (3 mega-accounts)", SkewSituation.Operation.JOIN, false, 3),
                new SkewSituation("txns ⋈ accounts (many moderate keys)", SkewSituation.Operation.JOIN, false, 0)
        );

        for (SkewSituation s : situations) {
            String rec = advisor.recommend(s);
            if (rec.startsWith("AQE")) {
                log.info("[" + s.getName() + "] -> " + rec);
            } else {
                log.warning("[" + s.getName() + "] -> " + rec);
            }
        }

        log.info("Order: enable AQE skew-join first; profile stragglers; escalate to salting / isolate-and-broadcast only if needed.");
    }
}

